SELECT status, CASE WHEN balance >= 89000 THEN 'LARGE' ELSE 'SMALL' END AS balance_tier, COUNT_IF(status = 'OPEN') AS open_events, APPROX_PERCENTILE(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN status = 'FROZEN' THEN 1 END), 0), 2) AS balance_per_frozen, MAX(balance) FILTER (WHERE status = 'FROZEN') AS frozen_max_balance, STDDEV_SAMP(balance) AS balance_stddev, COUNT(*) AS event_count FROM accounts GROUP BY status, CASE WHEN balance >= 89000 THEN 'LARGE' ELSE 'SMALL' END ORDER BY event_count NULLS LAST;
